#define BLUE vec3(0.,.1,.7)
#define CYAN vec3(.1,.5,.9)

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = 2.*(fragCoord-iResolution.xy*.5)/iResolution.y;

    vec3 col = vec3(1);

    col = mix(col, BLUE, step(length(uv),1.0));

    col = mix(CYAN, col, smoothstep(0.,1.,length(uv*mat2(
        1.0,0.0,
        0.0,1.0
    )+vec2(0,.5))));

    col = mix(col, mix(
        vec3(1),
        col,
        .9-uv.y*.8
    ), step(length(uv*mat2(
        1.0,0.0,
        0.0,1.5
    )+vec2(0,-0.7)),0.75));

    fragColor = vec4(pow(col,vec3(.454545)),1.0);
}
